content.query:
let UserActivity = 
    GloCo_PageViews_CaseReview
    | where TimeGenerated > datetime(2026-03-09T12:00:01)
    | summarize FirstSeen = bin(min(TimeGenerated), 1d), 
                LastSeen = bin(max(TimeGenerated), 1d) 
              by Auth_Username;
let FirstSeenCounts = 
    UserActivity 
    | summarize FirstSeenCount = count() by Day = FirstSeen;
let LastSeenCounts = 
    UserActivity 
    | summarize LastSeenCount = count() by Day = LastSeen;
FirstSeenCounts
| join kind=fullouter LastSeenCounts on Day
| project Day = coalesce(Day, Day1), 
          FirstSeenCount = coalesce(FirstSeenCount, 0), 
          LastSeenCount = coalesce(LastSeenCount, 0)
| order by Day asc
